    /// <summary>
    /// Find method to fetch METExciseRegisterOriginTypes
    /// </summary>
    /// <param name = "_referenceId">ReferenceId reference</param>
    /// <param name = "_transactionType">Transaction type</param>
    /// <param name = "_forUpdate">Boolean to update</param>
    /// <returns>METExciseRegisterOriginTypes</returns>
    public static METExciseRegisterOriginTypes find(InventTransType         _referenceId,
                                                    METTransactionType      _transactionType,
                                                    boolean                 _forUpdate = false)
    {
        METExciseRegisterOriginTypes        metExciseRegisterOriginTypes;

        if (_forUpdate)
        {
            metExciseRegisterOriginTypes.selectForUpdate(true);
        }

        select firstonly metExciseRegisterOriginTypes
            where metExciseRegisterOriginTypes.ReferenceId == _referenceId  &&
                metExciseRegisterOriginTypes.TransactionType == _transactionType;

        return metExciseRegisterOriginTypes;
    }

/// <summary>
/// Exist method to fetch existance of record
/// </summary>
/// <param name = "_referenceId">ReferenceId reference</param>
/// <param name = "_transactionType">Transaction type</param>
/// <returns>Boolean</returns>
public static boolean exist(InventTransType         _referenceId,
                            METTransactionType      _transactionType)
{
    return (select firstonly RecId from metExciseRegisterOriginTypes
                where metExciseRegisterOriginTypes.ReferenceId == _referenceId  &&
                    metExciseRegisterOriginTypes.TransactionType == _transactionType).RecId != 0;
}
